import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicReference;

public class Main {
    static final ThreadLocal<String> TX_CONTEXT = new ThreadLocal<>();

    public static void main(String[] args) throws Exception {
        // 单线程 + 正确清理：上下文正确
        AtomicReference<Boolean> singleOk = new AtomicReference<>(false);
        AtomicReference<Boolean> cleanAfterRemove = new AtomicReference<>(false);
        Thread t = new Thread(() -> {
            TX_CONTEXT.set("tx-A");
            singleOk.set("tx-A".equals(TX_CONTEXT.get()));
            TX_CONTEXT.remove();
            cleanAfterRemove.set(TX_CONTEXT.get() == null);
        });
        t.start();
        t.join();
        System.out.println("single thread: context correct: " + singleOk.get());
        System.out.println("single thread: after remove() context null: " + cleanAfterRemove.get());

        // 线程池复用且不清理：第二个任务读到上一个任务的残留上下文
        ExecutorService pool = Executors.newFixedThreadPool(1);
        pool.submit(() -> TX_CONTEXT.set("tx-1")).get();          // 不 remove
        AtomicReference<String> seen = new AtomicReference<>();
        pool.submit(() -> seen.set(TX_CONTEXT.get())).get();
        System.out.println("thread-pool reuse leaks previous tx context: "
                + "tx-1".equals(seen.get()));
        pool.shutdown();
    }
}
